import{weekly as u}from"./derive.min.js";export const SENT=["applied","screening","interviewing"],OFFERS=["offer","accepted"];const f=n=>n.company||n.role||"them";export function celebrationFor(n,o,a,l){const d=new Map(n.applications.map(e=>[e.id,e])),i=[],r=[];for(const e of o.applications){if(e.deletedAt||e.sample)continue;const s=d.get(e.id);if(s&&s.deletedAt)continue;const p=s?s.status:null;OFFERS.includes(e.status)&&!OFFERS.includes(p)?r.push(e):SENT.includes(e.status)&&(!s||p==="saved")&&i.push(e)}const t=u(o,l);if(r.length){const e=r[0],s=e.status==="accepted"?`You accepted the offer from ${f(e)}. Congratulations!`:`An offer from ${f(e)}. Congratulations!`;return{kind:"offer",apps:r,week:t,line:s}}if(!i.length)return null;if(u(n,l).count<t.goal&&t.count>=t.goal)return{kind:"goal",apps:i,week:t,line:`That makes ${t.count} this week, your weekly goal. Wonderful work!`};let c;return i.length>1?c=`${i.length} applications sent. That's ${t.count} this week.`:t.count<=1?c="Application sent. That's your first this week.":t.remaining>0?c=`Application sent. That's ${t.count} this week, ${t.remaining} to go.`:c=`Application sent. That's ${t.count} this week.`,{kind:"applied",apps:i,week:t,line:c}}const g=(n,o)=>n.getFullYear()===o.getFullYear()&&n.getMonth()===o.getMonth()&&n.getDate()===o.getDate();export function champagneToday(n,o){return n.applications.some(a=>{if(a.deletedAt||!OFFERS.includes(a.status))return!1;const l=a.statusAt||a.createdAt;return!!l&&g(new Date(l),o)})}
